   [67]={next_id=68, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="而你，狮刃。一个受人尊敬的战斗教官，一个在伊凡城有深刻过往的人，却当做纯粹保镖和我们安排在一起……", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_15_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
